using Markout;

// Verbosity is the caller's concept; the model + IncludeSections is all Markout ever sees.
// Diagnostics is the deepest/most expensive detail, so it demands the highest verbosity.
const string Dependencies = "Dependencies";
const string Diagnostics = "Diagnostics";

