Emit(new[] { "(none)" });

// 2. Target ONLY Diagnostics by name — promoting verbosity so it is collected,
//    yet rendering Diagnostics and NOT Dependencies.
Emit(new[] { Diagnostics });

// 3. Detailed — both Dependencies and Diagnostics.
