void Emit(string[] requestedSections)
{
    // Resolve the required verbosity from the requested sections, then collect only that deep.
    var required = GetRequiredVerbosity(requestedSections);
    var pkg = Collect(required);

    var options = new MarkoutWriterOptions
    {
        IncludeSections = new HashSet<string>(requestedSections),
    };
    MarkoutSerializer.Serialize(pkg, Console.Out, new MarkdownFormatter(), PackageContext.Default, options);
    Console.WriteLine();
}

Verbosity GetRequiredVerbosity(string[] sections)
{
    var level = Verbosity.Quiet;
    foreach (var s in sections)
    {
        if (s == Diagnostics) level = (Verbosity)Math.Max((int)level, (int)Verbosity.Detailed);
        else if (s == Dependencies) level = (Verbosity)Math.Max((int)level, (int)Verbosity.Normal);
    }
    return level;
}

