    ("Dependencies", Verbosity.Detailed),
    ("Diagnostics", Verbosity.Diagnostic),
};

void Emit(string label, Verbosity requested, params string[] targets)
{
    // Targeting a section by name promotes the effective verbosity to whatever that
    // section needs to be collected.
    var effective = requested;
    foreach (var name in targets)
        foreach (var s in catalog)
            if (s.Name == name && s.Needed > effective)
                effective = s.Needed;

    var report = Collect(effective);

    // Render filter: explicit targets when given, otherwise every section the effective
    // verbosity has collected. An empty set renders no detail sections at all.
    var include = targets.Length > 0
        ? new HashSet<string>(targets)
        : new HashSet<string>(catalog.Where(s => s.Needed <= effective).Select(s => s.Name));

    Console.WriteLine($"===== {label} report (verbosity: {effective}) =====\n");
    var options = new MarkoutWriterOptions { IncludeSections = include };
    MarkoutSerializer.Serialize(report, Console.Out, PackageReportContext.Default, options);
    Console.WriteLine();
}

// Builds the report, only paying for a detail section's data when the effective verbosity
// warrants it. Diagnostics is the deepest/most expensive detail.
PackageReport Collect(Verbosity verbosity) => new()
{
    Id = "Serilog",
    Downloads = 500_000_000,
    Dependencies = verbosity >= Verbosity.Detailed
        ? new() { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } }
        : new(),
    Diagnostics = verbosity >= Verbosity.Diagnostic
        ? new() { new() { Level = "warning", Text = "transitive version conflict" } }
        : new(),
};

enum Verbosity { Quiet, Detailed, Diagnostic }

[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
    public string Id { get; init; } = "";
    public long Downloads { get; init; }

    [MarkoutSection(Name = "Dependencies")]
    public List<Dep> Dependencies { get; init; } = new();

    [MarkoutSection(Name = "Diagnostics")]
    public List<Diagnostic> Diagnostics { get; init; } = new();
}

[MarkoutSerializable]
public sealed class Dep { public string Name { get; init; } = ""; public string Version { get; init; } = ""; }

[MarkoutSerializable]
public sealed class Diagnostic { public string Level { get; init; } = ""; public string Text { get; init; } = ""; }

[MarkoutContext(typeof(PackageReport))]
[MarkoutContext(typeof(Dep))]
[MarkoutContext(typeof(Diagnostic))]
public partial class PackageReportContext : MarkoutSerializerContext { }
